def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = sorted({v for row in grid for v in row if v != 0})
    shapes = []
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        shapes.append([[grid[r][c] for c in range(c0, c1 + 1)]
                       for r in range(r0, r1 + 1)])
    out = [[0] * sum(len(shape[0]) for shape in shapes) for _ in range(max(map(len, shapes)))]
    offset = 0
    for shape in shapes:
        for r in range(len(shape)):
            for c in range(len(shape[0])):
                out[r][offset + c] = shape[r][c]
        offset += len(shape[0])
    return out
